jQuery(document).ready(function($){(new function(){this.defaultHTMLPrices={},this.init=function(){$(document).on("found_variation",(event,variation)=>{var priceContainer,event=jQuery(event.target).closest(".variations_form").find('input[name="product_id"]').val();void 0===this.defaultHTMLPrices[event]&&(priceContainer=this.$getPriceContainer(event)).length&&(this.defaultHTMLPrices[event]=priceContainer.html()),variation.price_html?this.updatePrice(event,variation.price_html):this.updatePrice(event,this.defaultHTMLPrices[event])}),$(document).on("reset_data",event=>{event=jQuery(event.target).closest(".variations_form").find('input[name="product_id"]').val();void 0!==this.defaultHTMLPrices[event]&&this.updatePrice(event,this.defaultHTMLPrices[event])})},this.$getPriceContainer=function(productId){return $('.cpdfw-variable-product-price[data-product-id="'+productId+'"]')},this.updatePrice=function(productId,priceHTML){productId=this.$getPriceContainer(productId);productId.length&&productId.html(priceHTML)}}).init()});
